/* ---------- Kabine ---------- */
function fire(k){
  if(S.confirm!==k){S.confirm=k;render();return;}
  S.cand={k,l:[cd(),cd(),cd()]};S.confirm=null;save();render();return;
  const old=S.M[k].name;
  S.M[k]={name:NAMES1[Math.floor(Math.random()*16)]+' '+NAMES2[Math.floor(Math.random()*16)],sk:Math.round(rnd(3,9)),note:'Yeni atanan isim'};
  S.cur.spent+=3;S.confirm=null;S.par=clamp(S.par-0.3,0,10);
  S.log.push({m:S.month,t:'Kabine değişikliği',c:`${k==='mb'?'Merkez Bankası Başkanı':minName(k)+' Bakanı'} değişti`,msg:`${old} görevden alındı. ${S.M[k].name} atandı (yetkinlik ${S.M[k].sk}/10).`});
  save();render();
}
function lever(k,dir){
  const r=LVR[k];const nv=Math.round((S.lv[k]+dir*r[2])*100)/100;
  if(nv<r[0]||nv>r[1])return;
  const old=S.lv[k];S.lv[k]=nv;
  const after=levCost();S.lv[k]=old;
  const before=levCost();
  if(after>before&&avail()<1)return;
  S.lv[k]=nv;save();render();
}

/* ---------- Ek özellikler: rehber, başarım, anket, sektör, dış ilişki, yuvalar ---------- */
const ls=(k,v)=>{try{if(v===undefined)return localStorage.getItem(k);localStorage.setItem(k,v);}catch(e){}return null;};
const base=()=>20-4*(S.dif===undefined?1:S.dif);
const TUT=[['Karar Masası\'na hoş geldin','Her ay bir turdur. Ayda 3 olay çıkar, her olay için bir seçenek seçersin. Eylemlerin bekleme süresi yoktur; aynı eylemi üst üste tekrarlamak etkisini azaltır.'],['Göstergeler','Masa sekmesinde 16 gösterge var. Birine dokunursan geçmiş grafiği açılır. Halk desteği çok düşerse hükümet düşer, rezerv biterse ekonomi çöker.'],['Kararlar ve faiz','Kararlar sayfasında olaylara dokunup seçim yap, politika faizini ayarla. Hazır olunca Ayı Bitir\'e bas.'],['Bütçe, vergi ve devlet','Ekonomi sekmesinde bakanlık bütçeleri, vergi oranları ve sektörler var. Devlet sekmesinde Merkez Bankası, Hazine, savunma ve dış ilişkiler.'],['Siyaset ve seçim','İlk genel seçim Haziran 2028\'de, sonra beş yılda birdir. Cumhurbaşkanlığı için %50+1 gerekir, olmazsa ikinci tur yapılır. Meclis\'te yasa çıkarır, ittifak kurar ve vaat verirsin. Tutmadığın vaat oy kaybettirir. İyi şanslar.']];
const tutScreen=()=>{const n=S.tut,t=TUT[n-1];return `<div class="wrap"><div class="end"><div class="muted dl">Rehber ${n}/${TUT.length}</div><h1>${t[0]}</h1><p>${t[1]}</p><div class="chips"><button class="btn" data-tutn="1">${n<TUT.length?'İleri':'Başla'}</button><button class="btn sec" data-tutn="0">Atla</button></div></div></div>`;};
const ACH=[['ilk','İlk yasa',()=>Object.keys(S.laws).length>0],['yas5','5 yasa çıkardın',()=>Object.keys(S.laws).length>=5],['enf','Enflasyon %20 altına indi',()=>S.enf<20],['buy','Büyüme %5 üstüne çıktı',()=>S.buy>=5],['isz','İşsizlik %6 altına indi',()=>S.isz<6],['rez','Rezerv 60 mlr $',()=>S.rez>=60],['des','Halk desteği %60',()=>S.des>=60],['gd','GSYH 2 trilyon $',()=>S.gdp>=2000],['koal','İttifak kurdun',()=>S.coal.length>0],['anl','3 anlaşma veya proje',()=>Object.keys(S.done).length>=3],['yil','5 yıl dayandın',()=>S.month>=60],['sec','Seçimi kazandın',()=>S.term>1],['bel','15+ büyükşehir belediyesi',()=>S.mun>=15]];
function checkAch(){const n=[];ACH.forEach(([id,t,f])=>{if(!S.ach[id]&&f()){S.ach[id]=S.month+1;n.push('Başarım: '+t);}});return n;}
const basarim=()=>`<h2>Başarımlar (${Object.keys(S.ach).length}/${ACH.length})</h2><div class="panel">${ACH.map(([id,t])=>`<div class="lever"><span class="n">${t}</span><span class="h">${S.ach[id]?'Kazanıldı · '+dateLabel(S.ach[id]-1):'Henüz değil'}</span></div>`).join('')}<div style="margin-top:8px"><button class="btn sec sm" data-tut="1">Rehberi göster</button></div></div>`;
const slots=()=>`<h2>Kayıt Yuvaları</h2><div class="panel">${[1,2,3].map(i=>`<div class="lever"><span class="n">Yuva ${i}</span><span class="h">${ls('km-sm'+i)||'Boş'}</span><div class="step">${sbtn(`data-slot="s${i}"`,'Kaydet')}${ls('km-s'+i)?sbtn(`data-slot="l${i}"`,'Yükle'):''}</div></div>`).join('')}</div>`;
function loadCode(v){try{const o=JSON.parse(decodeURIComponent(escape(atob(v))));if(!o||typeof o.month!=='number'||!o.M||typeof o.enf!=='number')throw 0;S=o;ensure();S.tab='masa';S.kmsg='';save();render();return true;}catch(e){return false;}}
const karne=()=>{const H=S.hist,mx=k=>Math.max(...H[k]),mn=k=>Math.min(...H[k]);return `<div class="panel" style="margin-top:14px"><b>Karne</b><div class="dl">Süre: ${S.month} ay (${nf(S.month/12,1)} yıl) · ${S.term}. dönem</div><div class="dl">Çıkardığın yasa: ${Object.keys(S.laws).length}</div><div class="dl">En yüksek büyüme %${nf(mx('buy'),1)} · en düşük enflasyon %${nf(mn('enf'),1)}</div><div class="dl">Halk desteği: en yüksek %${nf(mx('des'),1)}, en düşük %${nf(mn('des'),1)}</div><div class="dl">Büyükşehir ${S.mun}/30 · Anlaşma ve proje: ${Object.keys(S.done).length}</div></div>`;};
function startGame(k){S.me=k;S.pick=false;initGov();S.pool=base();S.h0=0;
  if(S.sc===1){Object.assign(S,{enf:68,kur:62,rez:6,des:32,buy:.5,acik:7,borc:52,isz:11.5});S.gdp=1150;}
  if(S.sc===2){S.month=14;S.des=44;S.h0=14;}
  S.hd=Math.round(S.enf*.6);S.gv=50;STATS.forEach(s=>S.hist[s.k]=[S[s.k]]);S.prev=snap();S.mun={AKP:12,CHP:14,DEM:3,YRP:1}[k]??0;S.pl=[];poll();S.pri=[];S.prip=1;S.prg=[];S.cpi=100;
  dunyaEnsure();toplumEnsure(true);piyasaEnsure();ileriEnsure();genisEnsure();genis2Ensure();partiEnsure();S.debt=S.borc*S.gdp/100;S.nel=20;arayuzEnsure();if(!ls('km-tut'))S.tut=1;save();render();}
/* anketler, belediyeler, sektörler */
function poll(){if(S.pl.length>40)S.pl=S.pl.slice(-40);const p=S.pl[S.pl.length-1],me=pvt(),o={},ks=PK.filter(k=>k!==S.me);let z=0;ks.forEach(k=>{o[k]=(p?p[k]:PART[k].w)*(1+rnd(-.04,.04));z+=o[k];});ks.forEach(k=>o[k]=o[k]/z*(100-me));o[S.me]=me;S.pl.push(o);}
const PCOL=['#28597F','#B02A30','#A96B0C','#1E7A4B','#7A4FA0','#56666E'];
const anket=()=>{const H=S.pl.slice(-13),n=H.length;if(n<2)return '';const all=H.flatMap(o=>PK.map(k=>o[k])),mx=Math.max(...all)+2,mn=Math.max(0,Math.min(...all)-2),X=i=>30+i/(n-1)*280,Y=v=>10+(1-(v-mn)/(mx-mn))*110;
  return `<div class="panel"><b>Seçim anketleri</b><svg class="ch" viewBox="0 0 320 130"><text x="26" y="14" text-anchor="end">${nf(mx,0)}</text><text x="26" y="124" text-anchor="end">${nf(mn,0)}</text><line x1="30" x2="310" y1="10" y2="10"/><line x1="30" x2="310" y1="120" y2="120"/>${PK.map((k,j)=>`<polyline style="stroke:${PCOL[j]}" points="${H.map((o,i)=>X(i).toFixed(1)+','+Y(o[k]).toFixed(1)).join(' ')}"/>`).join('')}</svg><div class="chips">${PK.map((k,j)=>`<span class="chip" style="border-left:4px solid ${PCOL[j]}">${PART[k].n} %${nf(H[n-1][k],1)}</span>`).join('')}</div></div>`;};
const belediye=()=>`<div class="panel"><b>Belediyeler</b><div class="dl">Büyükşehir belediyesi: ${S.mun} / 30</div><div class="note">Sonraki yerel seçim: ${dateLabel(S.month<29?29:29+Math.ceil((S.month-28)/TERM)*TERM)}. ${S.mun>=15?'Belediyelerin çoğu sende, parti örgütü güçlü.':'Belediyelerin çoğu elinde değil, örgüt zayıf.'}</div></div>`;
const rb=k=>S.bud[k]/MB[k]-1;
function secUp(){const t={tur:50+(S.bat-5)*5+(S.huz-5)*5+rb('kultur')*30,tar:50+rb('tarim')*40,san:50+rb('sanayi')*40+(S.buy-2.8)*6-(S.enf-E0)*.1,ene:50+rb('enerji')*40+(S.rez-22)*.2+(S.dog-5)*2},s=S.sec;for(const k in t)s[k]=clamp(s[k]+(t[k]-s[k])*.1+rnd(-1.5,1.5),0,100);
  S.buy=clamp(S.buy+((s.tur+s.tar+s.san+s.ene)/4-50)*.003,-12,12);S.cari=clamp(S.cari-(s.tur-50)*.004,2,90);S.enf=clamp(S.enf-(s.tar-50)*.003,2,300);S.par=clamp(S.par+(S.mun-10)*.003,0,10);}
/* anlaşma, proje, özelleştirme: [id, ad, SS, etki, açıklama, (tekrar ayı)] */
const DEALS=[['ab','AB gümrük birliği güncellemesi',3,{bat:1.5,cari:-1,dog:-.3,des:.5},'Batı ile ticaret genişler.'],['brics','BRICS ortaklığı',3,{dog:1.5,bat:-1,rez:2,des:.3},'Doğu ile bağlar güçlenir.'],['golf','Körfez yatırım paketi',2,{rez:6,dog:.6,bol:.4,des:.3},'Yatırım ve döviz girişi.'],['ots','Türk devletleriyle enerji ve ulaşım anlaşması',2,{dog:1,bol:.6,cari:-.8,des:.4},'Ortak enerji hatları ve ticaret koridoru.'],['dam','Doğu Akdeniz uzlaşması',3,{bol:1,bat:.5,cari:-1,huz:.2},'Enerji arama hakları paylaşılır.'],['nato','NATO ortak savunma projesi',2,{bat:1,ord:.3,dog:-.4},'İttifakta ağırlığın artar.']];
const PROJ=[['siha','SİHA filosunu genişlet',3,{ord:1,cari:-.5,dog:.3,acik:.3},'Yerli üretim insansız araçlar.'],['gemi','Milli savaş gemisi programı',3,{ord:.8,bat:.2,acik:.4},'Tersaneler iş alır.'],['ucak','Milli muharip uçak',4,{ord:1.5,cari:.8,bat:-.3,acik:.6},'Uzun vadeli, pahalı proje.'],['hava','Hava savunma sistemi',3,{ord:1,bat:-.4,dog:.4,acik:.4},'Yabancı ve yerli sistemler.'],['siber','Siber savunma merkezi',2,{ord:.4,huz:.3,acik:.15},'Kritik altyapıyı korur.'],['tat','Ortak tatbikat',1,{ord:.6,bol:-.2,acik:.1},'Ordu moralini artırır.',6]];
const PRIV=[['bank','Kamu bankası hissesi sat',2,{acik:-1.2,des:-.8,huz:-.2,par:-.3},'Büyük gelir, sendikalar tepkili.'],['tel','Telekom ve şeker fabrikalarını sat',2,{acik:-.7,des:-.5,isz:.2},'Orta gelir, işten çıkarma riski.'],['ene','Enerji santrallerini sat',3,{acik:-1.5,des:-1.2,enf:.3,par:-.4},'En büyük gelir, elektrik fiyatı riski.'],['ulas','Otoyol ve köprüleri sat',2,{acik:-.8,des:-.6},'Geçiş ücretleri artabilir.'],['hav','Havalimanı işletmelerini sat',2,{acik:-.6,des:-.3,bat:.2},'Yatırımcıya açılır.']];
const AL=[...DEALS,...PROJ,...PRIV],isDone=e=>S.done[e[0]]&&S.month<S.done[e[0]];
const listPanel=(t,L,n)=>`<h2>${t}</h2><div class="panel">${L.map(e=>`<div class="lever"><span class="n">${e[1]}</span><span class="h">${e[4]} (Etkisi: ${fxText(e[3])}.)</span><div class="step">${isDone(e)?'<span class="st good">Yapıldı</span>':sbtn(`data-deal="${e[0]}"`,`Uygula`,avail()<e[2])}</div></div>`).join('')}${n?`<div class="note">${n}</div>`:''}</div>`;
const DQ={ab:['ger'],dam:['gre'],golf:['sau','qat'],ots:['aze'],nato:['usa'],brics:['rus','chn']};
function dealAct(id){const e=AL.find(x=>x[0]===id);if(!e||isDone(e)||e[2]>avail())return;if(DQ[id]&&S.ul&&DQ[id].some(c=>S.ul[c]<50)){S.done[id]=0;logA('Devlet',e[1],'Karşı taraf hazır değil: '+DQ[id].map(c=>CT.find(x=>x[0]===c)[1]+' ilişkisi 50 olmalı').join(', ')+'.');save();render();return;}const m=e[5]?su('d_'+id):1;if(e[5])suU('d_'+id);applyFx(sfx2(e[3],m));if(PRIV.includes(e)&&e[3].acik)S.acikP=(S.acikP||0)-e[3].acik*.25;if(DQ[id])DQ[id].forEach(c=>{S.ul[c]=clamp(S.ul[c]+3,0,100);});S.done[id]=e[5]?0:S.month+9999;S.cur.spent+=e[2];logA('Devlet',e[1],'Uygulandı.');save();render();}
const dis=()=>listPanel('Anlaşmalar ve ittifaklar',DEALS,'Her anlaşma bir kez yapılır. Karşı ülkelerle ilişki en az 50 olmalı (AB: Almanya, Doğu Akdeniz: Yunanistan, Körfez: Suudi Arabistan ve Katar, Türk devletleri: Azerbaycan, NATO: ABD, BRICS: Rusya ve Çin).')+listPanel('Savunma projeleri',PROJ,'Projeler bir kez, tatbikat istediğin kadar tekrarlanabilir. Bütçe açığı etkisi ay ay yansır.');
function sektor(){return `<h2>Sektörler</h2><div class="panel">${[['tur','Turizm','Kültür ve Turizm bütçesi, Batı itibarı, huzur'],['tar','Tarım','Tarım bütçesi'],['san','Sanayi','Sanayi bütçesi, büyüme, enflasyon'],['ene','Enerji','Enerji bütçesi, rezerv, Doğu itibarı']].map(([k,n,h])=>`<div style="display:grid;grid-template-columns:70px minmax(0,1fr) 34px;gap:10px;align-items:center;margin-top:10px"><span>${n}</span><div class="bar"><i style="width:${S.sec[k]}%"></i></div><span class="dl">${nf(S.sec[k],0)}</span></div><div class="note" style="margin:2px 0 0">${h}</div>`).join('')}<div class="note">Ortalama 50'nin üstündeyse büyüme artar. Turizm cari açığı azaltır, tarım enflasyonu düşürür.</div></div>${listPanel('Özelleştirme',PRIV,'Kamu varlığı sat, bütçe açığını kapat. Halk tepki gösterebilir.')}`;}
const prep=()=>clamp(.4+((S.bud.ic/MB.ic+S.bud.cevre/MB.cevre)/2-1)*.9,.1,.9);
/* ---------- Ek özellikler 2: bakan adayı, yasa taslağı, PPK, dış ticaret, harita, tema, ses ---------- */
const TP={tek:['Teknokrat',{kur:-.5,par:-.2}],pop:['Popülist',{des:.5,acik:.3}],sad:['Sadık',{par:.4}],ref:['Reformcu',{bat:.4,par:-.2}]};
const cd=()=>{const tp=Object.keys(TP)[Math.floor(Math.random()*4)],m=newM();m.tp=tp;if(tp==='tek')m.sk=Math.min(10,m.sk+1);if(tp==='sad')m.sk=Math.max(2,m.sk-1);return m;};
function appoint(i){const c=S.cand.l[i],k=S.cand.k,old=S.M[k].name;if(avail()<2)return;S.M[k]={name:c.name,sk:c.sk,note:TP[c.tp][0],gv:55};applyFx(TP[c.tp][1]);S.cur.spent+=2;S.par=clamp(S.par-.3,0,10);S.cand=null;logA('Kabine değişikliği',`${k==='mb'?'Merkez Bankası Başkanı':minName(k)+' Bakanı'} değişti`,`${old} görevden alındı. ${c.name} atandı (${TP[c.tp][0]}, yetkinlik ${c.sk}/10).`);save();render();}
const candP=()=>`<div class="panel"><b>${S.cand.k==='mb'?'Merkez Bankası Başkanı':minName(S.cand.k)+' Bakanı'} için aday seç</b>${S.cand.l.map((c,i)=>`<div class="lever"><span class="n">${c.name}</span><span class="h">${TP[c.tp][0]} · yetkinlik ${c.sk}/10 · ${fxText(TP[c.tp][1])}</span><div class="step">${sbtn(`data-ap="${i}"`,'Ata',avail()<2)}</div></div>`).join('')}<div style="margin-top:8px"><button class="btn sec sm" data-apx="1">Vazgeç</button></div></div>`;
const YT=[['mv','Vergi indirimi',{des:1.2,acik:.5,buy:.3},.7],['mya','Sosyal yardım artışı',{des:1.5,huz:.5,acik:.4},.7],['mis','Kamu istihdam programı',{isz:-.5,des:.8,acik:.5},.6],['myu','Yerli üretim desteği',{buy:.4,cari:-.8,acik:.3},.5],['men','Enerji verimliliği',{cari:-.6,buy:.2,acik:.2,bat:.3},.5],['mkr','Kira ve konut düzenlemesi',{des:1,huz:.4,buy:-.2},.6]],YL=['Hafif','Orta','Sert'];
function draft(){const b=S.dr.b||0,lv=S.dr.l===undefined?1:S.dr.l,t=YT[b],f=[.6,1,1.5][lv],fx={};for(const k in t[2])fx[k]=Math.round(t[2][k]*f*100)/100;return [t[0]+lv+'_'+S.month,`${t[1]} (${YL[lv]})`,2+lv,301,clamp(t[3]-lv*.1,.1,.9),`Kendi taslağın: ${t[1].toLowerCase()}, ${YL[lv].toLowerCase()} kapsam.`,fx];}
function submitDraft(){const l=draft();if(l[2]>avail())return;S.cl=S.cl.slice(-19).concat([l]);propose(l[0],false);}
const draftP=()=>{const l=draft();return `<h2>Yasa Taslağı</h2><div class="panel"><div class="dl">Konu</div><div class="chips" style="margin:6px 0">${YT.map((t,i)=>`<button class="btn sm ${(S.dr.b||0)===i?'':'sec'}" data-drb="${i}">${t[1]}</button>`).join('')}</div><div class="dl">Kapsam</div><div class="chips" style="margin:6px 0">${YL.map((n,i)=>`<button class="btn sm ${(S.dr.l===undefined?1:S.dr.l)===i?'':'sec'}" data-drl="${i}">${n}</button>`).join('')}</div><div class="note"><b>${l[1]}</b> (Geçerse: ${fxText(l[6])}.) Kapsam arttıkça etki ve maliyet büyür, Meclis'te destek azalır.</div>${sbtn('data-dsub="1"',`Taslağı sun`,avail()<l[2])}</div>`;};
/* Merkez Bankası toplantısı ve dış ticaret */
const mbRec=()=>Math.round(S.enf+3);
function mbUp(){S.gv=clamp(S.gv+(Math.abs(S.lv.faiz-mbRec())<=6?1:-1.2)+(S.enf<=S.hd+8?.6:-.4),0,100);}
/* Dış ticaret: başlangıç verileri TÜİK/TİM 2025 (ihracat 273,4 · ithalat 365,4 mlr $) */
const EXG=[['Otomotiv',41.5,.2,.5],['Kimya',31.9,.2,.3],['Elektrik-elektronik',17.7,.2,.4],['Hazır giyim',16.8,.6,.3],['Çelik',16.5,.5,.2],['Demir dışı metaller',13.2,.3,.2],['Makine',11.3,.3,.4],['Savunma-havacılık',10,.1,.3],['Tarım, gıda ve diğer',114.5,.3,.2]],EP=[['Almanya',22.2,'bat'],['Birleşik Krallık',16.8,'bat'],['ABD',16.3,'bat'],['İtalya',13.2,'bat'],['Irak',12.4,'bol']],IP=[['Çin',49.6,'dog'],['Rusya',42.4,'dog'],['Almanya',30.1,'bat'],['ABD',18.1,'bat'],['İsviçre',15.7,'bat']],FT={bat:'AB ve Batı',dog:'Asya-Pasifik',bol:'Körfez ve Afrika'};
const tk=()=>1.2*S.buy-(S.enf-E0)*.03+(S.des-40)*.03;
const mcomp=()=>{const k=(S.kur/K0)/((S.cpi||100)/100)-1;return [5*(S.tr.pe/70)*(1-(S.sec.ene-50)*.004),16.7*(1+.02*(S.buy-2.8)-k*.1)*(1-.03*S.yl),3.8*(1+.03*(S.buy-2.8)),4.86*(1+.05*(tk()-3.15))];};
const exg=()=>{const w=EXG.map(g=>g[1]*(1+g[2]*((S.kur/K0)/((S.cpi||100)/100)-1)+g[3]*(S.bat-5)/10+(S.sec.san-50)/250)),z=w.reduce((a,b)=>a+b,0);return w.map(v=>S.tr.x*v/z);};
const pv=(P,T,tot)=>{const v=P.map(p=>{const ci=typeof CT!=='undefined'&&S.ul?CT.find(c=>c[4]===p[0]):null;return tot*p[1]/T*(1+.04*(S[p[2]]-(p[2]==='bol'?6:5))+(S.fta[p[2]]?.06:0)+(ci?.004*(S.ul[ci[0]]-ci[3]):0));});return [...v,tot-v.reduce((a,b)=>a+b,0)];};
function tradeUp(){const t=S.tr,k=(S.kur/K0)/((S.cpi||100)/100)-1;t.pe=clamp(t.pe+rnd(-3,3)+(70-t.pe)*.06,35,150);
  const x=22.8*(1+k*.25+(S.sec.san-50)*.004+(S.bat-5)*.01+((S.cool.ihr||0)>S.month?.08:0)+Object.keys(S.fta).length*.02-.004*Math.max(0,S.tar-8)),m=mcomp().reduce((a,b)=>a+b,0)*(1-.006*S.tar);
  t.x=t.x*.8+.2*(x+rnd(-.5,.5));t.m=t.m*.8+.2*(m+rnd(-.5,.5));S.cari=clamp(S.cari+((t.m-t.x)-7.6)*.1,2,90);
  S.enf+=(S.tar-(S.tarL||0))*.1;S.tarL=(S.tarL||0)+(S.tar-(S.tarL||0))/12;S.bat=clamp(S.bat-S.tar*.004,0,10);S.sec.san=clamp(S.sec.san+S.tar*.02,0,100);}
function tact(a,v){if(a==='tar'){if(avail()<1)return;S.cur.spent+=1;S.tar=clamp(S.tar+ +v,0,30);}else{if(avail()<2)return;if(a==='yl'){if(S.yl>=5)return;S.yl++;S.sec.san=clamp(S.sec.san+2,0,100);applyFx({acik:.2});}else{if(S.fta[v])return;S.fta[v]=1;applyFx({[v]:.4});}S.cur.spent+=2;logA('Dış ticaret',a==='yl'?'Yerlileşme programı':'Serbest ticaret anlaşması ('+FT[v]+')','Uygulandı.');}hap(20,520);save();render();}
function ihr(){if(avail()<1)return;S.cool.ihr=S.month+12;S.cur.spent+=1;applyFx({acik:.3});logA('Dış ticaret','İhracat teşviki','12 ay geçerli olacak.');save();render();}
const ticaret=()=>{const t=S.tr,g=exg(),mc=mcomp(),z=mc.reduce((a,b)=>a+b,0),cl=Math.max(0,(S.cool.ihr||0)-S.month),a=avail(),ex=pv(EP,273.4,t.x*12),im=pv(IP,365.4,t.m*12),
  R=(n,v,mx,u)=>`<div style="display:grid;grid-template-columns:minmax(0,1fr) 56px 58px;gap:8px;align-items:center;padding:3px 0"><span>${n}</span><div class="bar"><i style="width:${Math.max(0,Math.min(100,v/mx*100))}%"></i></div><span class="dl" style="text-align:right">${nf(v,1)}</span></div>`,
  L=(rows,mx)=>rows.map(r=>R(r[0],r[1],mx)).join('');
  return `<h2>Dış Ticaret</h2><div class="panel"><div class="dl">Aylık ihracat ${nf(t.x,1)} · ithalat ${nf(t.m,1)} mlr $ · açık ${nf(t.m-t.x,1)} mlr $</div><div class="dl">Yıllık eşdeğer: ihracat ${nf(t.x*12,0)} · ithalat ${nf(t.m*12,0)} mlr $ · karşılama oranı %${nf(t.x/t.m*100,1)}</div><div class="dl">Brent petrol ${nf(t.pe,0)} $/varil · hanehalkı tüketimi yıllık %${nf(tk(),1)} (GSYH'nin yaklaşık %60'ı)</div><div class="note">Başlangıç: 2025 TÜİK ve TİM verileri (ihracat 273,4, ithalat 365,4, açık 92,0 mlr $). Tüm tablolar yıllık eşdeğer, mlr $.</div></div>
  <h2>İhracat · Sektörler</h2><div class="panel">${L(EXG.map((e,i)=>[e[0],g[i]*12]),45)}<div class="note">Zayıf TL hazır giyim ve çeliği, Batı ilişkileri otomotiv ve elektroniği, sanayi sektörü hepsini destekler.</div></div>
  <h2>İthalat · Kalemler</h2><div class="panel">${L([['Enerji',mc[0]],['Ara malı',mc[1]],['Yatırım malı',mc[2]],['Tüketim malı',mc[3]]].map(r=>[r[0],r[1]/z*t.m*12]),240)}<div class="note">Enerji: petrol fiyatı ve enerji sektörü; ara malı: büyüme, kur ve yerlileşme; tüketim: hanehalkı harcaması. Kalem payları yaklaşık değerdir.</div></div>
  <h2>Ticaret Ortakları</h2><div class="panel"><div class="dl">İhracat</div>${L([...EP.map((p,i)=>[p[0],ex[i]]),['Diğer ülkeler',ex[5]]],60)}<div class="dl" style="margin-top:8px">İthalat</div>${L([...IP.map((p,i)=>[p[0],im[i]]),['Diğer ülkeler',im[5]]],60)}<div class="note">Batı, Doğu ve Körfez ilişkilerin ve serbest ticaret anlaşmaların ortaklarla ticareti etkiler.</div></div>
  <h2>Ticaret Politikası</h2><div class="panel"><div class="lever"><span class="n">Ek gümrük tarifesi: %${S.tar}</span><span class="h">İthalatı kısar, yerli üretimi korur. Enflasyon ve Batı ilişkileri zarar görür, %8'in üstünde karşı tarife gelir.</span><div class="step">${sbtn('data-tar="-2"','−2',a<1||!S.tar)}${sbtn('data-tar="2"','+2',a<1||S.tar>=30)}</div></div><div class="lever"><span class="n">Yerlileşme programı: seviye ${S.yl}/5</span><span class="h">Ara malı ithalatını %3 azaltır, sanayiyi güçlendirir, bütçeye yük biner.</span><div class="step">${sbtn('data-yl="1"','Yükselt',a<2||S.yl>=5)}</div></div><div class="lever"><span class="n">İhracat teşviki</span><span class="h">12 ay boyunca ihracatı artırır.</span><div class="step">${sbtn('data-ihr="1"',cl?'Yenile ('+cl+' ay)':'Uygula',a<1)}</div></div>${Object.keys(FT).map(k=>`<div class="lever"><span class="n">Serbest ticaret: ${FT[k]}</span><span class="h">Kalıcı ihracat artışı ve ilişki puanı.</span><div class="step">${sbtn(`data-fta="${k}"`,S.fta[k]?'İmzalandı':'Müzakere',S.fta[k]||a<2)}</div></div>`).join('')}</div>`;};
const mbP=()=>`<div class="panel"><b>Merkez Bankası toplantısı (PPK)</b><div class="dl">Enflasyon hedefi: %${S.hd} · güvenilirlik ${nf(S.gv,0)}/100</div><div class="dl">PPK önerisi: faiz %${mbRec()} · senin faizin %${nf(S.lv.faiz,1)}</div><div class="note">Faizin öneriden en fazla 6 puan uzaksa güvenilirlik artar. Güvenilirlik düşerse kur baskı görür. Hedef her Aralık yenilenir.</div></div>`;
