const rv=(i,k)=>{const j=MAP.r[i],e=ilE(i),o=((i*37+11)%17-8)/2;return S[k]+REG[j][1][k]*(k==='des'&&PART[S.me].x<=.3?-1:1)+(k==='des'?o+e:k==='huz'?o*.05+e*.1:-o*.1-e*.1);};
