function rgAct(i,m){const c=1;if(avail()<c)return;const sm=su(m?'mit':'ily');suU(m?'mit':'ily');S.ri[i]=[Math.min(10,ilE(i)+(m?1.2:2.5)*sm),S.month];S.cur.spent+=c;if(m)S.kamp=clamp((S.kamp||0)+.25*sm,-6,3);else applyFx({des:.15*sm,acik:.15});logA(m?'Miting':'İl yatırımı',MAP.n[i],m?'Seçim mitingi yapıldı.':'İle kamu yatırımı yapıldı.');hap(20,520);save();render();}
const bolgeP=i=>{const camp=toEl()<=6,a=avail();return `<div class="panel" style="margin-top:10px"><b>${MAP.n[i]}</b> <span class="muted">· ${REG[MAP.r[i]][0]} Bölgesi</span>${IND.map(x=>`<div class="dl" style="display:flex;justify-content:space-between;padding:3px 0"><span>${x[1]}</span><span>${nf(rv(i,x[0]),1)}${x[2]} <small>(ülke ${nf(S[x[0]],1)})</small></span></div>`).join('')}<div class="dl">Yatırım etkisi: +${nf(ilE(i),1)} puan (2 yılda azalır)</div><div class="chips" style="margin-top:8px">${sbtn(`data-rgi="${i}"`,'İle yatırım',a<1)}${camp?sbtn(`data-rgm="${i}"`,'Miting',a<1):''}</div>${camp?'':'<div class="note">Miting yalnızca seçime son 6 ayda yapılabilir.</div>'}</div>`;};
function harita(){const I=IND.find(x=>x[0]===(S.mi||'des')),nat=S[I[0]],v=MAP.n.map((n,i)=>rv(i,I[0])),sp=Math.max(...v.map(x=>Math.abs(x-nat)),.01),ix=MAP.n.map((n,i)=>i),ord=ix.slice().sort((a,b)=>(a===S.rgs)-(b===S.rgs)),w=ix.slice().sort((a,b)=>(v[a]-v[b])*(I[3]?1:-1)).slice(0,4);
  return `<h2>Bölgesel Görünüm</h2><div class="panel"><div class="chips">${IND.map(x=>`<button class="btn sm ${x[0]===I[0]?'':'sec'}" data-mi="${x[0]}">${x[1]}</button>`).join('')}</div><svg class="ch" viewBox="0 0 ${MAP.w} ${MAP.h}" style="margin-top:8px">${ord.map(i=>{const t=(v[i]-nat)/sp*(I[3]?1:-1),c=t>=0?'var(--good)':'var(--bad)';return `<path data-il="${i}" d="${MAP.p[i]}" style="cursor:pointer;fill:${c};stroke:var(--bg);stroke-width:.25;${S.rgs===i?'filter:drop-shadow(0 0 1.2px var(--ink));':''}opacity:${(.3+.65*Math.abs(t)).toFixed(2)}"/>`;}).join('')}<path d="${MAP.b}" style="fill:none;stroke:var(--bg);stroke-width:.9;stroke-linecap:round;pointer-events:none"/>${REG.map((r,j)=>`<text x="${MAP.l[j][0]}" y="${MAP.l[j][1]}" text-anchor="middle" style="font-size:7px;font-weight:600;fill:var(--ink);pointer-events:none">${r[0]}</text>`).join('')}</svg><div class="note" style="margin-top:0">81 ilden birine dokun: ayrıntı, yatırım ve miting.</div><div class="dl">En zayıf iller:</div><div class="chips" style="margin:6px 0">${w.map(i=>`<button class="btn sm sec" data-il="${i}">${MAP.n[i]} ${nf(v[i],1)}${I[2]}</button>`).join('')}</div>${REG.map((r,j)=>`<div class="dl" style="display:flex;justify-content:space-between;padding:3px 0"><span>${r[0]} (ort.)</span><span>${nf(rav(j,I[0]),1)}${I[2]}</span></div>`).join('')}<div class="note">Yeşil iller ülke ortalamasından (${nf(nat,1)}${I[2]}) iyi, kırmızılar kötü durumda.</div></div>${S.rgs!=null?bolgeP(S.rgs):''}`;}
const sx=()=>{const H=S.hist,f=(k,g)=>`%${nf(g(...H[k]),1)} (${dateLabel(S.h0+H[k].indexOf(g(...H[k])))})`,lg=t=>S.log.filter(x=>x.c===t).length;return [`Karar: ${S.nd} · Yönetilen kriz: ${S.nk}`,`Yasa: ${lg('Kabul edildi')} kabul, ${lg('Reddedildi')} ret`,`Halk desteği en yüksek ${f('des',Math.max)}`,`Halk desteği en düşük ${f('des',Math.min)}`,`Enflasyon en düşük ${f('enf',Math.min)}`,`Büyüme en yüksek ${f('buy',Math.max)}`].map(x=>`<div class="dl">${x}</div>`).join('');};
const ist=()=>`<h2>İstatistikler</h2><div class="panel">${sx()}</div>`;
const ozet=e=>`<div class="panel" style="margin-top:14px;text-align:left"><b>Dönem karnesi</b>${e.pr.length?e.pr.map(r=>`<div class="dl">${r[1]?'✓ Tuttun':'✗ Tutamadın'}: ${r[0]}</div>`).join(''):'<div class="dl">Bu dönem vaat verilmemişti.</div>'}${sx()}</div>`;
/* tema, ses ve titreşim */
const th=v=>{try{if(v!==undefined)ls('km-th',v);const t=ls('km-th')||'';if(t)document.documentElement.setAttribute('data-theme',t);else document.documentElement.removeAttribute('data-theme');}catch(e){}};
const fxs=()=>ls('km-fx')!=='0';
function beep(f,d=.09){try{if(!fxs())return;const A=window.AudioContext||window.webkitAudioContext,c=beep.c||(beep.c=new A()),o=c.createOscillator(),g=c.createGain();o.frequency.value=f;g.gain.value=.05;o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+d);}catch(e){}}
const hap=(p,f)=>{try{if(fxs()){navigator.vibrate&&navigator.vibrate(p);f&&beep(f);}}catch(e){}};
const ayar=()=>`<h2>Ayarlar</h2><div class="panel"><div class="dl">Tema</div><div class="chips" style="margin:6px 0 10px">${[['auto','Otomatik'],['light','Açık'],['dark','Koyu']].map(([v,n])=>`<button class="btn sm ${(ls('km-th')||'auto')===v?'':'sec'}" data-th="${v}">${n}</button>`).join('')}</div><div class="dl">Ses ve titreşim</div><div class="chips" style="margin-top:6px"><button class="btn sm ${fxs()?'':'sec'}" data-fx="1">${fxs()?'Açık':'Kapalı'}</button></div></div>`;
/* seçim kampanyası ve dönem hikâyeleri */
const DON={2:{t:'Yorgunluk dönemi',x:'Halk değişim istiyor, muhalefet güçlendi.',fx:{des:-2,par:-.3},ev:'t_yorgun'},3:{t:'Küresel fırtına',x:'Dünya ekonomisi sarsılıyor.',fx:{cari:1,enf:1.5,rez:-2},ev:'t_kuresel'}};
